using Ecom.Domain.Entities;

namespace Ecom.Application.Features.Commerce.Producers.Commands.UpdateProducerContact;
public sealed record UpdateProducerContactCommand(Guid ProducerId,Guid ContactId,Guid ProducerConcurrencyStamp,ContactType ContactType,string ContactValue,string? ContactName,bool IsPublic,int DisplayOrder):IRequest<TResult<ProducerContactDto>>,ITransactionalRequest;
public sealed class UpdateProducerContactCommandValidator:AbstractValidator<UpdateProducerContactCommand>{public UpdateProducerContactCommandValidator(){RuleFor(x=>x.ProducerId).NotEmpty();RuleFor(x=>x.ContactId).NotEmpty();RuleFor(x=>x.ProducerConcurrencyStamp).NotEmpty();RuleFor(x=>x.ContactValue).NotEmpty().MaximumLength(512);RuleFor(x=>x.ContactName).MaximumLength(256);RuleFor(x=>x.DisplayOrder).GreaterThanOrEqualTo(0);}}
public sealed class UpdateProducerContactCommandHandler(IUnitOfWork uow,ProducerManagementService service):IRequestHandler<UpdateProducerContactCommand,TResult<ProducerContactDto>>
{public async Task<TResult<ProducerContactDto>> Handle(UpdateProducerContactCommand r,CancellationToken ct){var loaded=await service.LoadAsync(r.ProducerId,r.ProducerConcurrencyStamp,Permissions.Producers.Update,ct);if(!loaded.IsSuccess)return TResult<ProducerContactDto>.Failure(loaded.Error!,loaded.ErrorCode);var contact=await uow.Repository<ProducerContact>().FindOneAsync([x=>x.Id==r.ContactId&&x.ProducerId==loaded.Data.Id]);if(contact is null)return TResult<ProducerContactDto>.Failure(MessageKey.ResourceNotFound,ErrorCodes.NOT_FOUND);contact.Update(r.ContactType,r.ContactValue,r.ContactName,r.IsPublic,r.DisplayOrder);loaded.Data.RenewConcurrencyStamp();await uow.Repository<ProducerContact>().UpdateAsync(contact,ct);await uow.Repository<Producer>().UpdateAsync(loaded.Data,ct);return TResult<ProducerContactDto>.Success(ProducerManagementService.Map(contact));}}
